// ============ CONFIG - EDIT ME ============
const DAYS_AFTER_COMPLETION = 3;   // send the ask N days after the job is done
const MAX_AGE_DAYS = 30;           // never chase jobs older than this (stale = awkward)
const BUSINESS_NAME = 'Acme Home Services';
const OWNER_NAME = 'Alex';
// Link to YOUR feedback form (Tally / Fillout / your site). The form should POST
// name, email, rating, message to this workflow's 'Review Reply Webhook'.
const FEEDBACK_URL = 'https://YOUR-FEEDBACK-FORM-URL';
// ==========================================

const out = [];
const today = new Date();

for (const item of $input.all()) {
  const j = item.json;
  const status = String(j['Status'] || '').trim().toLowerCase();
  const email = String(j['Email'] || '').trim();
  const alreadySent = String(j['Review Requested'] || '').trim();
  const rawDate = String(j['Completion Date'] || '').trim();

  if (status !== 'completed') continue;          // only finished jobs
  if (!email || !email.includes('@')) continue;  // no valid email -> nothing to send
  if (alreadySent) continue;                     // already asked -> NEVER double-send
  if (!rawDate) continue;                        // no completion date -> can't compute timing

  const done = new Date(rawDate);
  if (isNaN(done.getTime())) continue;           // unparseable date -> skip safely

  const days = Math.floor((today - done) / 86400000);
  if (days < DAYS_AFTER_COMPLETION || days > MAX_AGE_DAYS) continue;

  const name = String(j['Customer Name'] || '').trim();
  out.push({ json: {
    job_id: String(j['Job ID'] || '').trim(),
    customer_name: name,
    first_name: name.split(' ')[0] || 'there',
    email: email,
    job_type: String(j['Job Type'] || 'recent job').trim(),
    technician: String(j['Technician'] || '').trim(),
    completion_date: rawDate,
    days_since: days,
    business_name: BUSINESS_NAME,
    owner_name: OWNER_NAME,
    feedback_url: FEEDBACK_URL
  }});
}

// Empty array = nothing due today; downstream nodes simply don't run.
return out;

// Safely parse the AI's JSON. If the model returns junk, fall back to a
// solid hand-written template so the send NEVER fails or goes out broken.
const jobs = $('Find Jobs Due').all();

return $input.all().map((item, i) => {
  const job = jobs[i] ? jobs[i].json : {};
  let subject = 'How did we do, ' + (job.first_name || 'there') + '?';
  let body = 'Hi ' + (job.first_name || 'there') + ',\n\nThanks for choosing ' + (job.business_name || 'us') + ' for your ' + (job.job_type || 'recent job') + '. We would love to hear how everything went - it takes 30 seconds:\n' + (job.feedback_url || '') + '\n\nThanks again,\n' + (job.owner_name || '') + '\n' + (job.business_name || '');
  let used_fallback_template = true;

  try {
    let raw = ((item.json.choices || [])[0] || {}).message ? item.json.choices[0].message.content : '';
    raw = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(raw);
    if (parsed.subject && parsed.body) {
      subject = String(parsed.subject);
      body = String(parsed.body);
      used_fallback_template = false;
    }
  } catch (e) {
    // keep the safe fallback template
  }

  return { json: Object.assign({}, job, { subject, body, used_fallback_template }) };
});

// ============ CONFIG - EDIT ME ============
const OWNER_EMAIL = 'owner@yourbusiness.com';   // where private alerts go
const OWNER_NAME = 'Alex';
const BUSINESS_NAME = 'Acme Home Services';
// Your public review link (Google Business Profile 'write a review' URL works great)
const PUBLIC_REVIEW_LINK = 'https://g.page/r/YOUR_GOOGLE_REVIEW_ID/review';
// ==========================================

// Accept JSON bodies, form posts, or query params - form tools all differ.
const hook = $json;
const src = (hook.body && Object.keys(hook.body).length) ? hook.body : (hook.query || {});

const pick = (...keys) => {
  for (const k of keys) {
    const v = src[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const name = pick('name', 'Name', 'customer_name', 'full_name');
const email = pick('email', 'Email', 'customer_email').toLowerCase();
const message = pick('message', 'Message', 'feedback', 'Feedback', 'comments', 'review', 'text');
const ratingRaw = pick('rating', 'Rating', 'stars', 'score');
const rating = (ratingRaw && !isNaN(Number(ratingRaw)))
  ? Math.max(1, Math.min(5, Math.round(Number(ratingRaw))))
  : null;

// A reply with neither text nor a rating is noise (bots, empty form submits).
const valid = Boolean(message || rating);

return [{ json: {
  name: name,
  first_name: name.split(' ')[0] || 'there',
  email: email,
  message: message,
  rating: rating,
  valid: valid,
  response_message: valid ? 'Feedback received - thank you!' : 'No rating or message found in the payload.',
  owner_email: OWNER_EMAIL,
  owner_name: OWNER_NAME,
  business_name: BUSINESS_NAME,
  review_link: PUBLIC_REVIEW_LINK
} }];

// Safely parse the classifier output. Fail-safe design: if the AI response
// can't be parsed, we treat it as NEGATIVE so it routes to the owner and a
// human looks at it. Nothing ever gets silently lost.
const reply = $('Normalize Reply').first().json;
const item = $input.first();

let sentiment = 'negative';
let confidence = 0;
let summary = 'AI response could not be parsed - routing to owner for manual review.';
let testimonial_quote = '';
let suggested_action = 'Read the raw feedback below and reply personally.';
let ai_parse_error = true;

try {
  let raw = ((item.json.choices || [])[0] || {}).message ? item.json.choices[0].message.content : '';
  raw = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const p = JSON.parse(raw);
  if (['positive', 'neutral', 'negative'].includes(p.sentiment)) {
    sentiment = p.sentiment;
    confidence = Number(p.confidence) || 0;
    summary = String(p.summary || '');
    testimonial_quote = String(p.testimonial_quote || '');
    suggested_action = String(p.suggested_action || '');
    ai_parse_error = false;
  }
} catch (e) {
  // keep fail-safe defaults
}

// Only send the public-review ask when the customer is CLEARLY happy AND we
// actually have an email address to send it to. Neutral goes to the owner.
const is_happy = !ai_parse_error
  && sentiment === 'positive'
  && Boolean(reply.email)
  && (reply.rating === null || reply.rating >= 4);

return [{ json: Object.assign({}, reply, {
  sentiment: sentiment,
  confidence: confidence,
  summary: summary,
  testimonial_quote: testimonial_quote,
  suggested_action: suggested_action,
  ai_parse_error: ai_parse_error,
  is_happy: is_happy,
  routed_to: is_happy ? 'public review ask' : 'owner alert'
}) }];

